import Foundation
import TabProtocol
import XCTest
@testable import TabServer

/// Provider request contracts: L2 permission and elicitation cards, L3 offered decisions,
/// L5 child-origin routing. The Codex shapes follow the app-server schema generated by
/// `codex app-server generate-json-schema --experimental` from codex-cli 0.169.0
/// (`PermissionsRequestApprovalParams`, `McpServerElicitationRequestParams`,
/// `CommandExecutionRequestApprovalParams.availableDecisions`, `ServerRequestResolvedNotification`,
/// `collabAgentToolCall.receiverThreadIds`, `thread/closed`). The Claude shape follows
/// Claude Code 2.1.311's `can_use_tool` control request, whose `agent_id` names the
/// subagent that asked. They are hand-written replays of those schemas, not recordings.
final class AgentInteractionContractTests: XCTestCase {
    private static let codexHandshake = """
    take
    emit '{"id":1,"result":{}}'
    take
    take
    emit '{"id":2,"result":{"thread":{"id":"thread"}}}'
    take
    emit '{"id":3,"result":{"turn":{"id":"turn"}}}'
    """

    private func wait(_ recorder: AgentRuntimeRecorder, _ what: String,
                      until predicate: ([String: AgentChatItem]) -> Bool) async throws {
        for _ in 0..<500 {
            if predicate(recorder.transcript) { return }
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTFail("Timed out waiting for \(what)")
    }

    private func responses(_ fixture: AgentRuntimeFixture) throws -> [[String: Any]] {
        try fixture.messages().filter { $0["method"] == nil && ($0["result"] != nil || $0["error"] != nil) }
    }

    private func response(_ fixture: AgentRuntimeFixture, id: Any) throws -> [String: Any]? {
        try responses(fixture).first { message in
            if let number = id as? Int { return (message["id"] as? NSNumber)?.intValue == number && !(message["id"] is String) }
            return message["id"] as? String == id as? String
        }
    }

    func testCodexPermissionsElicitationsAndOfferedDecisionsReachNativeCardsAndProviderExactly() async throws {
        let recorder = AgentRuntimeRecorder()
        let fixture = try AgentRuntimeFixture(Self.codexHandshake + """

        emit '{"id":7,"method":"item/permissions/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"p1","cwd":"/repo","reason":"Needs the network","startedAtMs":1,"permissions":{"network":{"enabled":true},"fileSystem":{"write":["/repo/build"]}}}}'
        emit '{"id":"7","method":"item/commandExecution/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"c1","startedAtMs":1,"command":"make","availableDecisions":["acceptForSession","decline"]}}'
        emit '{"id":8,"method":"item/commandExecution/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"c2","startedAtMs":1,"command":"rm -rf build","availableDecisions":["cancel"]}}'
        emit '{"id":9,"method":"item/fileChange/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"f1","startedAtMs":1}}'
        emit '{"id":"elic-1","method":"mcpServer/elicitation/request","params":{"threadId":"thread","turnId":"turn","serverName":"billing","mode":"form","message":"Pick a plan","requestedSchema":{"type":"object","properties":{"plan":{"type":"string","oneOf":[{"const":"pro","title":"Pro"},{"const":"free","title":"Free"}]},"seats":{"type":"integer"},"notify":{"type":"boolean"}},"required":["plan"]}}}'
        emit '{"id":10,"method":"mcpServer/elicitation/request","params":{"threadId":"thread","serverName":"auth","mode":"openai/userVerification","challenge":"x","description":"Verify","title":"Verify"}}'
        take
        emit '{"id":11,"method":"mcpServer/elicitation/request","params":{"threadId":"thread","serverName":"docs","mode":"form","message":"Nested","requestedSchema":{"type":"object","properties":{"nested":{"type":"object"}}}}}'
        take
        emit '{"id":12,"method":"mcpServer/elicitation/request","params":{"threadId":"thread","serverName":"auth","mode":"url","elicitationId":"e1","message":"Sign in","url":"https://example.com/auth"}}'
        emit '{"id":14,"method":"mcpServer/elicitation/request","params":{"threadId":"thread","serverName":"auth","mode":"url","elicitationId":"e2","message":"Again","url":"https://example.com/again"}}'
        emit '{"id":13,"method":"item/commandExecution/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"c3","startedAtMs":1,"command":"ls","availableDecisions":["accept","decline"]}}'
        emit '{"method":"serverRequest/resolved","params":{"threadId":"thread","requestId":13}}'
        take
        take
        take
        take
        take
        take
        take
        emit '{"method":"turn/completed","params":{"threadId":"thread","turn":{"id":"turn","status":"completed"}}}'
        hold
        """)
        defer { fixture.remove() }
        let runtime = fixture.runtime(.codex, recorder: recorder)
        defer { runtime.stop() }
        try await runtime.send(text: "Go", model: "test-model")
        try await wait(recorder, "every card") { $0["13"]?.isComplete == true && $0["14"] != nil }

        let state = recorder.transcript
        // Numeric 7 and string "7" are different requests.
        let permissions = try XCTUnwrap(state["7"]?.approval)
        XCTAssertEqual(permissions.kind, "permissions")
        XCTAssertEqual(permissions.decisions.map(\.id), ["turn", "session", "decline"])
        XCTAssertEqual(permissions.decisions.map(\.title), ["Allow for this turn", "Allow for this session", "Decline"])
        XCTAssertTrue(permissions.requested.contains(.init(label: "Network", value: "Internet access")))
        XCTAssertTrue(permissions.requested.contains(.init(label: "Write", value: "/repo/build")))
        XCTAssertEqual(permissions.summary, "Needs the network")
        XCTAssertEqual(permissions.origin?.numericID, true)
        let noOneTime = try XCTUnwrap(state["7#string"]?.approval)
        XCTAssertEqual(noOneTime.decisions.map(\.kind), [.allowForSession, .decline])
        XCTAssertNil(noOneTime.origin?.numericID)
        XCTAssertEqual(state["8"]?.approval?.decisions.map(\.kind), [.cancel])
        XCTAssertEqual(state["9"]?.approval?.decisions.map(\.id), ["accept", "acceptForSession", "decline", "cancel"],
                       "No offered list means the schema's whole set")
        let form = try XCTUnwrap(state["elic-1"]?.questionnaire)
        XCTAssertEqual(form.questions.map(\.id), ["notify", "plan", "seats"])
        XCTAssertEqual(form.questions.first { $0.id == "plan" }?.options.map(\.label), ["Pro", "Free"])
        XCTAssertEqual(form.questions.first { $0.id == "plan" }?.required, true)
        XCTAssertEqual(state["elic-1"]?.approval?.decisions.map(\.kind), [.submit, .decline, .cancel])
        XCTAssertEqual(state["12"]?.approval?.requested.last, .init(label: "Link", value: "https://example.com/auth"))
        XCTAssertNil(state["10"], "Unsupported schemas get no card")
        XCTAssertNil(state["11"])
        XCTAssertEqual(state["13"]?.approval?.outcome?.source, .provider, "Resolved elsewhere")
        XCTAssertEqual(try response(fixture, id: 10)?["error"].map { _ in true }, true)
        XCTAssertEqual(try response(fixture, id: 11)?["error"].map { _ in true }, true)

        try await runtime.decide(request: "7", decision: "session", answers: nil)
        do {
            try await runtime.approve(request: "7#string", allow: true)
            XCTFail("A request without one-time acceptance can't be allowed once")
        } catch { XCTAssertTrue(error.localizedDescription.contains("one-time")) }
        try await runtime.decide(request: "7#string", decision: "decline", answers: nil)
        try await runtime.approve(request: "8", allow: false) // Deny on a cancel-only request cancels.
        try await runtime.decide(request: "9", decision: "acceptForSession", answers: nil)
        do {
            try await runtime.decide(request: "elic-1", decision: "accept", answers: ["plan": ["Pro"], "seats": ["three"]])
            XCTFail("A typed field rejects a wrong value")
        } catch {}
        try await runtime.decide(request: "elic-1", decision: "accept", answers: ["plan": ["Pro"], "seats": ["3"], "notify": ["Yes"]])
        try await runtime.decide(request: "12", decision: "decline", answers: nil)
        try await runtime.decide(request: "14", decision: "cancel", answers: nil)
        do {
            try await runtime.decide(request: "13", decision: "accept", answers: nil)
            XCTFail("An answer to a request resolved elsewhere says so")
        } catch { XCTAssertTrue(error.localizedDescription.contains("elsewhere")) }
        try await wait(recorder, "turn end") { _ in recorder.statuses.last == .idle }

        let granted = try XCTUnwrap(try response(fixture, id: 7)?["result"] as? [String: Any])
        XCTAssertEqual(granted["scope"] as? String, "session")
        XCTAssertEqual(((granted["permissions"] as? [String: Any])?["network"] as? [String: Any])?["enabled"] as? Bool, true)
        XCTAssertEqual((try response(fixture, id: "7")?["result"] as? [String: Any])?["decision"] as? String, "decline")
        XCTAssertEqual((try response(fixture, id: 8)?["result"] as? [String: Any])?["decision"] as? String, "cancel")
        XCTAssertEqual((try response(fixture, id: 9)?["result"] as? [String: Any])?["decision"] as? String, "acceptForSession")
        let accepted = try XCTUnwrap(try response(fixture, id: "elic-1")?["result"] as? [String: Any])
        XCTAssertEqual(accepted["action"] as? String, "accept")
        let content = try XCTUnwrap(accepted["content"] as? [String: Any])
        XCTAssertEqual(content["plan"] as? String, "pro")
        XCTAssertEqual(content["seats"] as? Int, 3)
        XCTAssertEqual(content["notify"] as? Bool, true)
        XCTAssertEqual((try response(fixture, id: 12)?["result"] as? [String: Any])?["action"] as? String, "decline")
        XCTAssertEqual((try response(fixture, id: 14)?["result"] as? [String: Any])?["action"] as? String, "cancel")
        XCTAssertNil(try response(fixture, id: 13), "Nothing is sent for a request settled elsewhere")
        XCTAssertEqual(try responses(fixture).count, 9)

        // The card's history agrees with what was sent.
        let settled = recorder.transcript
        XCTAssertEqual(settled["7"]?.approval?.outcome?.decision, "session")
        XCTAssertEqual(settled["7"]?.text, "Approved for this session")
        XCTAssertEqual(settled["7#string"]?.approval?.outcome?.decision, "decline")
        XCTAssertEqual(settled["8"]?.approval?.outcome?.kind, .cancel)
        XCTAssertEqual(settled["8"]?.text, "Declined and stopped the response")
        XCTAssertEqual(settled["9"]?.approval?.outcome?.title, "Allow for this session")
        XCTAssertEqual(settled["elic-1"]?.approval?.outcome?.kind, .submit)
        XCTAssertEqual(settled["12"]?.approval?.outcome?.decision, "decline")
        XCTAssertEqual(settled["14"]?.approval?.outcome?.decision, "cancel")
        XCTAssertEqual(settled["7"]?.approval?.requested, permissions.requested, "What was asked stays with the answer")
    }

    func testCodexDisconnectEndsPendingRequestsAndRefusesLateAnswers() async throws {
        let recorder = AgentRuntimeRecorder()
        let fixture = try AgentRuntimeFixture(Self.codexHandshake + """

        emit '{"id":30,"method":"item/permissions/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"p1","cwd":"/repo","startedAtMs":1,"permissions":{"network":{"enabled":true}}}}'
        sleep 0.3
        exit 3
        """)
        defer { fixture.remove() }
        let runtime = fixture.runtime(.codex, recorder: recorder)
        defer { runtime.stop() }
        try await runtime.send(text: "Go", model: "test-model")
        try await wait(recorder, "the request to end") { $0["30"]?.isComplete == true }
        XCTAssertEqual(recorder.transcript["30"]?.approval?.outcome?.source, .expired)
        do {
            try await runtime.decide(request: "30", decision: "turn", answers: nil)
            XCTFail("The provider is gone")
        } catch {}
    }

    /// L5: overlapping requests from the conversation's own thread and two Codex agents;
    /// one agent ends before anyone answers.
    func testCodexChildRequestsKeepTheirOriginAndAnEndedChildsRequestExpires() async throws {
        let recorder = AgentRuntimeRecorder()
        let fixture = try AgentRuntimeFixture(Self.codexHandshake + """

        emit '{"method":"item/started","params":{"threadId":"thread","turnId":"turn","item":{"id":"spawn-a","type":"collabAgentToolCall","tool":"spawnAgent","status":"inProgress","senderThreadId":"thread","receiverThreadIds":["child-a"],"prompt":"Explore the parser","agentsStates":{}}}}'
        emit '{"method":"item/started","params":{"threadId":"thread","turnId":"turn","item":{"id":"spawn-b","type":"collabAgentToolCall","tool":"spawnAgent","status":"inProgress","senderThreadId":"thread","receiverThreadIds":["child-b"],"prompt":"Run the tests","agentsStates":{}}}}'
        emit '{"id":20,"method":"item/commandExecution/requestApproval","params":{"threadId":"thread","turnId":"turn","itemId":"c-parent","startedAtMs":1,"command":"parent-cmd","availableDecisions":["accept","decline"]}}'
        emit '{"id":21,"method":"item/commandExecution/requestApproval","params":{"threadId":"child-a","turnId":"child-a-turn","itemId":"c-a","startedAtMs":1,"command":"child-a-cmd","availableDecisions":["accept","decline"]}}'
        emit '{"id":22,"method":"item/permissions/requestApproval","params":{"threadId":"child-b","turnId":"child-b-turn","itemId":"p-b","cwd":"/repo","startedAtMs":1,"permissions":{"network":{"enabled":true}}}}'
        emit '{"method":"thread/closed","params":{"threadId":"child-a"}}'
        take
        take
        emit '{"method":"turn/completed","params":{"threadId":"thread","turn":{"id":"turn","status":"completed"}}}'
        hold
        """)
        defer { fixture.remove() }
        let runtime = fixture.runtime(.codex, recorder: recorder)
        defer { runtime.stop() }
        try await runtime.send(text: "Go", model: "test-model")
        try await wait(recorder, "three cards") { $0["20"] != nil && $0["22"] != nil && $0["21"]?.isComplete == true }
        let state = recorder.transcript
        XCTAssertEqual(state["20"]?.approval?.origin?.isChild, false)
        XCTAssertEqual(state["20"]?.approval?.origin?.threadID, "thread")
        let childA = try XCTUnwrap(state["21"]?.approval)
        XCTAssertEqual(childA.origin?.childAgentID, "child-a")
        XCTAssertEqual(childA.origin?.childToolUseID, "spawn-a")
        XCTAssertEqual(childA.origin?.childTitle, "Explore the parser")
        XCTAssertEqual(childA.outcome?.source, .expired)
        XCTAssertEqual(state["22"]?.approval?.origin?.childToolUseID, "spawn-b")
        XCTAssertEqual(state["22"]?.isComplete, false)
        do {
            try await runtime.decide(request: "21", decision: "accept", answers: nil)
            XCTFail("A late answer to an ended agent is refused")
        } catch { XCTAssertTrue(error.localizedDescription.contains("ended")) }
        try await runtime.decide(request: "22", decision: "turn", answers: nil)
        try await runtime.decide(request: "20", decision: "accept", answers: nil)
        try await wait(recorder, "turn end") { _ in recorder.statuses.last == .idle }
        let sent = try responses(fixture)
        XCTAssertEqual(sent.map { ($0["id"] as? NSNumber)?.intValue }, [22, 20], "Each answer reaches its own requester; none reaches the ended agent")
        XCTAssertEqual((sent[0]["result"] as? [String: Any])?["scope"] as? String, "turn")
        XCTAssertEqual((sent[1]["result"] as? [String: Any])?["decision"] as? String, "accept")
    }

    func testClaudeSubagentRequestCarriesAgentIdentityAndExpiresWhenItsAgentReturns() async throws {
        let recorder = AgentRuntimeRecorder()
        let fixture = try AgentRuntimeFixture("""
        take
        emit '{"type":"control_response","response":{"subtype":"success","request_id":"1","response":{}}}'
        take
        emit '{"type":"system","subtype":"init","session_id":"claude-session","model":"test-model"}'
        emit '{"type":"assistant","message":{"id":"m1","content":[{"type":"tool_use","id":"toolu_agent","name":"Agent","input":{"description":"Inspect logs","prompt":"Look"}}]}}'
        emit '{"type":"assistant","message":{"id":"m2","content":[{"type":"tool_use","id":"toolu_child","name":"Bash","input":{"command":"tail log"}}]},"parent_tool_use_id":"toolu_agent","agent_id":"a97"}'
        emit '{"type":"control_request","request_id":"child-req","request":{"subtype":"can_use_tool","tool_name":"Bash","display_name":"Bash","tool_use_id":"toolu_child","agent_id":"a97","input":{"command":"tail log"}}}'
        emit '{"type":"assistant","message":{"id":"m3","content":[{"type":"tool_use","id":"toolu_main","name":"Bash","input":{"command":"pwd"}}]}}'
        emit '{"type":"control_request","request_id":"main-req","request":{"subtype":"can_use_tool","tool_name":"Bash","tool_use_id":"toolu_main","input":{"command":"pwd"}}}'
        sleep 0.3
        emit '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"toolu_agent","content":"Agent finished"}]}}'
        take
        emit '{"type":"result","subtype":"success","is_error":false,"result":"done"}'
        hold
        """)
        defer { fixture.remove() }
        let runtime = fixture.runtime(.claude, recorder: recorder)
        defer { runtime.stop() }
        try await runtime.send(text: "Hi", model: "test-model")
        try await wait(recorder, "both cards") { $0["main-req"] != nil && $0["child-req"]?.isComplete == true }
        let child = try XCTUnwrap(recorder.transcript["child-req"]?.approval)
        XCTAssertEqual(child.origin?.childAgentID, "a97")
        XCTAssertEqual(child.origin?.childToolUseID, "toolu_agent")
        XCTAssertEqual(child.origin?.childTitle, "Inspect logs")
        XCTAssertEqual(child.outcome?.source, .expired)
        XCTAssertEqual(recorder.transcript["main-req"]?.approval?.decisions.map(\.kind), [.decline, .allowAlways, .allowOnce])
        do {
            try await runtime.approve(request: "child-req", allow: true)
            XCTFail("The subagent already returned")
        } catch {}
        try await runtime.decide(request: "main-req", decision: "allow", answers: nil)
        try await wait(recorder, "turn end") { _ in recorder.statuses.last == .idle }
        let answers = try fixture.messages().filter { $0["type"] as? String == "control_response" }
        XCTAssertEqual(answers.compactMap { ($0["response"] as? [String: Any])?["request_id"] as? String }, ["main-req"])
    }

    /// L4: Codex reports the exhausted window's reset in `account/rateLimits/updated`
    /// (`RateLimitSnapshot.primary.resetsAt`, seconds) and the stop as an `error` whose
    /// `codexErrorInfo` is `usageLimitExceeded`.
    func testCodexUsageLimitFailureCarriesTheReportedResetTime() async throws {
        let recorder = AgentRuntimeRecorder()
        let fixture = try AgentRuntimeFixture(Self.codexHandshake + """

        emit '{"method":"account/rateLimits/updated","params":{"rateLimits":{"primary":{"usedPercent":100,"resetsAt":1950000000,"windowDurationMins":300},"secondary":{"usedPercent":40,"resetsAt":1960000000}}}}'
        emit '{"method":"error","params":{"threadId":"thread","turnId":"turn","willRetry":false,"error":{"message":"You have hit your usage limit.","codexErrorInfo":"usageLimitExceeded"}}}'
        hold
        """)
        defer { fixture.remove() }
        let runtime = fixture.runtime(.codex, recorder: recorder)
        defer { runtime.stop() }
        try await runtime.send(text: "Go", model: "test-model")
        try await wait(recorder, "the failure") { _ in recorder.statuses.last == .failed }
        let limited = recorder.activities.compactMap { $0 }.last
        XCTAssertEqual(limited?.kind, .rateLimited)
        XCTAssertEqual(limited?.resumesAt, Date(timeIntervalSince1970: 1_950_000_000))
    }
}
